-- LOCAL PRO ONLY. Immutable private blobs, explicit per-version/channel manifests.
-- No old table/function replacement, sends, notifications, messages or billing.
begin;
create table if not exists public.pro_daily_log_file_heads(owner_id uuid not null,work_id text not null,log_id uuid not null,revision integer not null check(revision>0),primary key(owner_id,work_id,log_id),foreign key(owner_id,work_id,log_id) references pro_daily_logs(owner_id,work_id,id) on delete cascade);
create table if not exists public.pro_daily_log_files(id uuid primary key,owner_id uuid not null,work_id text not null,log_id uuid not null,source_name text not null check(length(source_name) between 1 and 160),name text not null check(length(name) between 1 and 160),mime_type text not null check(mime_type in('image/jpeg','application/pdf')),size_bytes integer not null check(size_bytes between 1 and 20971520),raw_sha256 text not null check(raw_sha256~'^[a-f0-9]{64}$'),sha256 text not null check(sha256~'^[a-f0-9]{64}$'),object_path text not null unique,ready boolean not null default false,ready_revision integer,created_by uuid not null,created_by_name text not null check(length(created_by_name)<=160),created_grant_id uuid,source_invite_id uuid,created_at timestamptz not null default now(),unique(owner_id,work_id,log_id,id),foreign key(owner_id,work_id,log_id) references pro_daily_logs(owner_id,work_id,id) on delete cascade,check((created_grant_id is null)=(source_invite_id is null)),check((ready and ready_revision is not null and ready_revision>0) or(not ready and ready_revision is null)),check(mime_type<>'image/jpeg' or size_bytes<=20971520),check(object_path=owner_id::text||'/'||id::text||case when mime_type='application/pdf' then '.pdf' else '.jpg' end));
create index if not exists pro_daily_log_files_page on pro_daily_log_files(owner_id,work_id,log_id,ready,id);
create table if not exists public.pro_daily_log_file_actions(actor_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,owner_id uuid not null,work_id text not null,log_id uuid not null,grant_id uuid,generation uuid,input jsonb not null,input_hash text not null check(input_hash~'^[a-f0-9]{64}$'),result jsonb,before_state jsonb,after_state jsonb,at timestamptz not null default now(),primary key(actor_id,action_id),foreign key(owner_id,work_id,log_id) references pro_daily_logs(owner_id,work_id,id) on delete cascade);
create table if not exists public.pro_daily_log_published_files(owner_id uuid not null,work_id text not null,log_id uuid not null,version integer not null,channel text not null check(channel in('client','team')),file_id uuid not null,position integer not null check(position between 0 and 19),snapshot jsonb not null,primary key(owner_id,work_id,log_id,version,channel,file_id),unique(owner_id,work_id,log_id,version,channel,position),foreign key(owner_id,work_id,log_id,version) references pro_daily_log_versions(owner_id,work_id,log_id,version) on delete cascade,foreign key(owner_id,work_id,log_id,file_id) references pro_daily_log_files(owner_id,work_id,log_id,id) on delete no action deferrable initially deferred);
create or replace function public.pro_daily_log_file_json(p_file public.pro_daily_log_files) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('id',p_file.id,'ownerId',p_file.owner_id,'workId',p_file.work_id,'logId',p_file.log_id,'name',p_file.name,'mimeType',p_file.mime_type,'sizeBytes',p_file.size_bytes,'sha256',p_file.sha256,'ready',p_file.ready,'createdBy',p_file.created_by,'createdByName',p_file.created_by_name,'createdGrantId',p_file.created_grant_id,'sourceInviteId',p_file.source_invite_id,'createdAt',p_file.created_at)$$;
create or replace function public.pro_daily_log_file_snapshot(p_file public.pro_daily_log_files) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select pro_daily_log_file_json(p_file)-array['ownerId','workId','logId','ready','createdBy','createdByName','createdGrantId','sourceInviteId']$$;
create or replace function public.pro_daily_log_file_context(p_actor uuid,p_work text,p_log uuid,p_grant uuid default null,p_write boolean default false,p_generation uuid default null,p_check_generation boolean default false,p_allow_missing boolean default false) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare ctx jsonb;own uuid;l pro_daily_logs;head integer;has_log boolean;can_upload boolean;begin
 ctx:=pro_daily_log_context(p_actor,p_work,p_grant,false);own:=(ctx->>'ownerId')::uuid;
 if p_write and not((ctx->>'isOwner')::boolean or ctx->>'role'='contributor') then raise exception 'Read-only file access' using errcode='42501';end if;
 if p_check_generation and p_generation is distinct from(ctx->>'sourceInviteId')::uuid then if p_write then raise exception 'Upload generation changed' using errcode='40001';else raise exception 'Upload generation changed' using errcode='42501';end if;end if;
 select * into l from pro_daily_logs where owner_id=own and work_id=p_work and id=p_log;has_log:=found;
 if has_log then if not pro_daily_log_visible(p_actor,ctx,l) then raise exception 'Private log unavailable' using errcode='42501';end if;
 elsif not p_allow_missing then raise exception 'Save the draft before uploading' using errcode='42501';end if;
 can_upload:=((ctx->>'isOwner')::boolean or ctx->>'role'='contributor') and(not has_log or not l.archived);
 if p_write and(not has_log or not can_upload) then raise exception 'Upload access unavailable' using errcode='42501';end if;
 select revision into head from pro_daily_log_file_heads where owner_id=own and work_id=p_work and log_id=p_log;
 return jsonb_build_object('ownerId',own,'workId',p_work,'logId',p_log,'grantId',p_grant,'generation',(ctx->>'sourceInviteId')::uuid,'exists',has_log,'canUpload',can_upload,'revision',coalesce(head,0));
end $$;
create or replace function public.pro_daily_log_file_head_advance(p_owner uuid,p_work text,p_log uuid) returns integer language plpgsql security invoker set search_path=public,pg_temp as $$declare head integer;begin select revision into head from pro_daily_log_file_heads where owner_id=p_owner and work_id=p_work and log_id=p_log for update;head:=coalesce(head,0);if head>=2147483647 then raise exception 'File revision exhausted' using errcode='40001';end if;insert into pro_daily_log_file_heads values(p_owner,p_work,p_log,head+1) on conflict(owner_id,work_id,log_id) do update set revision=excluded.revision;return head+1;end $$;
create or replace function public.pro_daily_log_files_read(p_actor uuid,p_work text,p_log uuid,p_grant uuid default null,p_status text default 'ready',p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare ctx jsonb;own uuid;items jsonb;cursor_id uuid;begin
 ctx:=pro_daily_log_file_context(p_actor,p_work,p_log,p_grant);own:=(ctx->>'ownerId')::uuid;if p_status is null or p_status not in('ready','pending','all') then raise exception 'Invalid file status' using errcode='22023';end if;
 if p_after is not null and not exists(select 1 from pro_daily_log_files where owner_id=own and work_id=p_work and log_id=p_log and id=p_after and(p_status='all' or ready=(p_status='ready'))) then raise exception 'File cursor changed' using errcode='40001';end if;
 select coalesce(jsonb_agg(pro_daily_log_file_json(f::public.pro_daily_log_files) order by f.id),'[]'::jsonb) into items from(select * from pro_daily_log_files where owner_id=own and work_id=p_work and log_id=p_log and(p_status='all' or ready=(p_status='ready')) and(p_after is null or id>p_after) order by id limit 21)f;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('context',ctx,'items',items,'nextCursor',cursor_id);end $$;
create or replace function public.pro_daily_log_published_files_read(p_actor uuid,p_scope jsonb,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare ctx jsonb;items jsonb;cursor_pos integer;cursor_id uuid;begin
 ctx:=pro_daily_log_discussion_context(p_actor,p_scope);if p_after is not null then select position into cursor_pos from pro_daily_log_published_files where owner_id=(ctx->>'ownerId')::uuid and work_id=ctx->>'workId' and log_id=(ctx->>'logId')::uuid and version=(ctx->>'version')::integer and channel=ctx->>'channel' and file_id=p_after;if not found then raise exception 'Published file cursor changed' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(f.snapshot order by f.position,f.file_id),'[]'::jsonb) into items from(select * from pro_daily_log_published_files where owner_id=(ctx->>'ownerId')::uuid and work_id=ctx->>'workId' and log_id=(ctx->>'logId')::uuid and version=(ctx->>'version')::integer and channel=ctx->>'channel' and(p_after is null or(position,file_id)>(cursor_pos,p_after)) order by position,file_id limit 21)f;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('context',ctx,'items',items,'nextCursor',cursor_id);end $$;
create or replace function public.pro_daily_log_file_download(p_actor uuid,p_file uuid,p_work text default null,p_log uuid default null,p_grant uuid default null,p_generation uuid default null,p_check_generation boolean default false,p_scope jsonb default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare ctx jsonb;f pro_daily_log_files;manifest jsonb;begin
 if p_scope is null then ctx:=pro_daily_log_file_context(p_actor,p_work,p_log,p_grant,false,p_generation,p_check_generation);select * into f from pro_daily_log_files where id=p_file and owner_id=(ctx->>'ownerId')::uuid and work_id=p_work and log_id=p_log and ready;
 else ctx:=pro_daily_log_discussion_context(p_actor,p_scope);select snapshot into manifest from pro_daily_log_published_files where owner_id=(ctx->>'ownerId')::uuid and work_id=ctx->>'workId' and log_id=(ctx->>'logId')::uuid and version=(ctx->>'version')::integer and channel=ctx->>'channel' and file_id=p_file;if not found then return null;end if;select * into f from pro_daily_log_files where id=p_file and owner_id=(ctx->>'ownerId')::uuid and ready;end if;
 if f.id is null then return null;end if;return jsonb_build_object('objectPath',f.object_path,'name',coalesce(manifest->>'name',f.name),'mimeType',f.mime_type,'sizeBytes',f.size_bytes,'sha256',f.sha256);end $$;
create or replace function public.pro_daily_log_file_pending(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_daily_log_file_actions;ctx jsonb;f pro_daily_log_files;source pro_daily_log_files;begin
 select * into r from pro_daily_log_file_actions where actor_id=p_actor and action_id=p_action;if not found then raise exception 'Reservation missing' using errcode='42501';end if;
 ctx:=pro_daily_log_file_context(p_actor,r.work_id,r.log_id,r.grant_id,true,r.generation,true);if r.result is not null then return jsonb_build_object('result',r.result);end if;
 select * into f from pro_daily_log_files where owner_id=r.owner_id and work_id=r.work_id and log_id=r.log_id and id=(r.input->>'fileId')::uuid;if not found then raise exception 'Reservation missing' using errcode='42501';end if;
 if r.input->>'action'='copy' then perform pro_daily_log_file_context(p_actor,r.work_id,(r.input->>'sourceLogId')::uuid,r.grant_id);end if;
 return jsonb_build_object('result',null,'file',pro_daily_log_file_json(f),'objectPath',f.object_path,'source',r.before_state);
end $$;
create or replace function public.pro_daily_log_file_reserve(p_actor uuid,p_input jsonb,p_input_hash text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;fid uuid;wid text;lid uuid;gid uuid;gen uuid;ctx jsonb;own uuid;keys text[];expected text[];r pro_daily_log_file_actions;f pro_daily_log_files;source pro_daily_log_files;before_json jsonb;mime text;bytes integer;filename text;head integer;begin
 if jsonb_typeof(p_input) is distinct from 'object' or not coalesce(p_input_hash~'^[a-f0-9]{64}$',false) then raise exception 'Invalid file operation' using errcode='22023';end if;act:=p_input->>'action';
 if act='upload' then expected:=array['action','actionId','fileId','generation','grantId','logId','mimeType','name','rawSha256','sha256','sizeBytes','sourceName','workId'];elsif act='copy' then expected:=array['action','actionId','fileId','generation','grantId','logId','sourceFileId','sourceLogId','sourceSha256','workId'];else raise exception 'Invalid file action' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input)key;if keys is distinct from expected or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'fileId') is distinct from 'string' or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'logId') is distinct from 'string' or jsonb_typeof(p_input->'grantId') not in('string','null') or jsonb_typeof(p_input->'generation') not in('string','null') then raise exception 'Invalid file fields' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;fid:=(p_input->>'fileId')::uuid;wid:=p_input->>'workId';lid:=(p_input->>'logId')::uuid;gid:=(p_input->>'grantId')::uuid;gen:=(p_input->>'generation')::uuid;
 ctx:=pro_daily_log_file_context(p_actor,wid,lid,gid,true,gen,true);own:=(ctx->>'ownerId')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||p_actor::text||':'||aid::text,0));
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||own::text||':'||wid,0));if gid is not null then perform 1 from pro_team_grants where id=gid for share;end if;
 ctx:=pro_daily_log_file_context(p_actor,wid,lid,gid,true,gen,true);
 select * into r from pro_daily_log_file_actions where actor_id=p_actor and action_id=aid;if found then if r.input is distinct from p_input or r.input_hash<>p_input_hash then raise exception 'File action identity reused' using errcode='22023';end if;return pro_daily_log_file_pending(p_actor,aid);end if;
 if exists(select 1 from pro_daily_log_actions where actor_id=p_actor and action_id=aid) or exists(select 1 from pro_daily_log_files where id=fid) then raise exception 'File identity already used' using errcode='40001';end if;
 if(select count(*) from pro_daily_log_files where owner_id=own and work_id=wid)>=100 then raise exception 'File capacity exceeded' using errcode='40001';end if;
 if act='copy' then
  if jsonb_typeof(p_input->'sourceLogId') is distinct from 'string' or jsonb_typeof(p_input->'sourceFileId') is distinct from 'string' or not coalesce((p_input->>'sourceSha256')~'^[a-f0-9]{64}$',false) then raise exception 'Invalid copy source' using errcode='22023';end if;
  perform pro_daily_log_file_context(p_actor,wid,(p_input->>'sourceLogId')::uuid,gid);
  select * into source from pro_daily_log_files where owner_id=own and work_id=wid and log_id=(p_input->>'sourceLogId')::uuid and id=(p_input->>'sourceFileId')::uuid and ready for share;if not found then raise exception 'Copy source unavailable' using errcode='42501';end if;if source.sha256<>p_input->>'sourceSha256' then raise exception 'Copy source changed' using errcode='40001';end if;
  mime:=source.mime_type;bytes:=source.size_bytes;filename:=source.name;before_json:=jsonb_build_object('file',pro_daily_log_file_json(source),'objectPath',source.object_path);
 else
  if jsonb_typeof(p_input->'name') is distinct from 'string' or jsonb_typeof(p_input->'sourceName') is distinct from 'string' or length(p_input->>'sourceName') not between 1 and 160 or jsonb_typeof(p_input->'mimeType') is distinct from 'string' or p_input->>'mimeType' not in('image/jpeg','application/pdf') or jsonb_typeof(p_input->'sizeBytes') is distinct from 'number' or not coalesce((p_input->>'sizeBytes')~'^[0-9]{1,8}$',false) or not coalesce((p_input->>'sha256')~'^[a-f0-9]{64}$',false) or not coalesce((p_input->>'rawSha256')~'^[a-f0-9]{64}$',false) then raise exception 'Invalid canonical upload' using errcode='22023';end if;
  mime:=p_input->>'mimeType';bytes:=(p_input->>'sizeBytes')::integer;filename:=p_input->>'name';
 end if;
 if bytes not between 1 and 20971520 or mime='image/jpeg' and bytes>20971520 or length(filename) not between 1 and 160 or filename~'[[:cntrl:]/\\]' or mime='application/pdf' and right(filename,4)<>'.pdf' or mime='image/jpeg' and right(filename,4)<>'.jpg' then raise exception 'Invalid canonical file metadata' using errcode='22023';end if;
 head:=pro_daily_log_file_head_advance(own,wid,lid);
 insert into pro_daily_log_files(id,owner_id,work_id,log_id,source_name,name,mime_type,size_bytes,raw_sha256,sha256,object_path,created_by,created_by_name,created_grant_id,source_invite_id) values(fid,own,wid,lid,case when act='copy' then source.name else p_input->>'sourceName' end,filename,mime,bytes,case when act='copy' then source.sha256 else p_input->>'rawSha256' end,case when act='copy' then source.sha256 else p_input->>'sha256' end,own::text||'/'||fid::text||case when mime='application/pdf' then '.pdf' else '.jpg' end,p_actor,pro_team_name(p_actor),gid,gen) returning * into f;
 ctx:=pro_daily_log_file_context(p_actor,wid,lid,gid,true,gen,true);
 insert into pro_daily_log_file_actions(actor_id,action_id,owner_id,work_id,log_id,grant_id,generation,input,input_hash,before_state) values(p_actor,aid,own,wid,lid,gid,gen,p_input,p_input_hash,before_json);return pro_daily_log_file_pending(p_actor,aid);
end $$;
create or replace function public.pro_daily_log_file_ready(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare r pro_daily_log_file_actions;ctx jsonb;f pro_daily_log_files;head integer;answer jsonb;begin
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||p_actor::text||':'||p_action::text,0));
 select * into r from pro_daily_log_file_actions where actor_id=p_actor and action_id=p_action;if not found or r.input->>'action' not in('upload','copy') then raise exception 'Upload reservation unavailable' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||r.owner_id::text||':'||r.work_id,0));if r.grant_id is not null then perform 1 from pro_team_grants where id=r.grant_id for share;end if;
 ctx:=pro_daily_log_file_context(p_actor,r.work_id,r.log_id,r.grant_id,true,r.generation,true);if r.result is not null then return r.result;end if;
 if r.input->>'action'='copy' then perform pro_daily_log_file_context(p_actor,r.work_id,(r.input->>'sourceLogId')::uuid,r.grant_id);end if;
 select * into f from pro_daily_log_files where id=(r.input->>'fileId')::uuid and owner_id=r.owner_id and work_id=r.work_id and log_id=r.log_id for update;if not found or f.ready then raise exception 'Upload state changed' using errcode='40001';end if;
 head:=pro_daily_log_file_head_advance(r.owner_id,r.work_id,r.log_id);update pro_daily_log_files set ready=true,ready_revision=head where id=f.id returning * into f;
 answer:=jsonb_build_object('action',r.input->>'action','file',pro_daily_log_file_json(f),'revision',head);ctx:=pro_daily_log_file_context(p_actor,r.work_id,r.log_id,r.grant_id,true,r.generation,true);
 update pro_daily_log_file_actions set result=answer,after_state=answer where actor_id=p_actor and action_id=p_action;return answer;
end $$;
-- Both the legacy HTTP facade and the new publication endpoint call this wrapper.
-- Missing `files` stays missing in receipts. Old stored writer receipts stay untouched.
create or replace function public.pro_daily_log_publish_files(p_actor uuid,p_input jsonb,p_input_hash text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;wid text;lid uuid;keys text[];old_input jsonb;r pro_daily_log_file_actions;old_receipt pro_daily_log_actions;l pro_daily_logs;f pro_daily_log_files;ref jsonb;gref jsonb;channel_name text;head integer;ver integer;pos integer;client_files jsonb:='[]';team_files jsonb:='[]';snap jsonb;publication jsonb;answer jsonb;selected uuid[];begin
 if jsonb_typeof(p_input) is distinct from 'object' or p_input->>'action' is distinct from 'publish' or not coalesce(p_input_hash~'^[a-f0-9]{64}$',false) or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'logId') is distinct from 'string' then raise exception 'Invalid publication' using errcode='22023';end if;
 old_input:=p_input-'files';select array_agg(key order by key) into keys from jsonb_object_keys(old_input)key;if keys is distinct from array['action','actionId','client','grantId','logId','revision','team','workId'] or old_input->'grantId' is distinct from 'null'::jsonb then raise exception 'Invalid owner publication fields' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;wid:=p_input->>'workId';lid:=(p_input->>'logId')::uuid;perform pro_work_schedule_owner(p_actor,wid);
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-action:'||p_actor::text||':'||aid::text,0));perform pro_work_schedule_owner(p_actor,wid);
 select * into r from pro_daily_log_file_actions where actor_id=p_actor and action_id=aid;if found then if r.input is distinct from p_input or r.input_hash<>p_input_hash then raise exception 'Publication identity reused with different files' using errcode='22023';end if;return r.result;end if;
 select * into old_receipt from pro_daily_log_actions where actor_id=p_actor and action_id=aid;
 if found then
  if p_input?'files' or old_receipt.input is distinct from old_input then raise exception 'Legacy publication identity cannot acquire attachments' using errcode='22023';end if;
  publication:=pro_daily_logs_mutate(p_actor,old_input);return jsonb_build_object('action','publish','publication',publication,'files',jsonb_build_object('client','[]'::jsonb,'team','[]'::jsonb));
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||wid,0));
 -- Same request/grant/log ordering as the old writer; no work row lock.
 if old_input->'client'<>'null'::jsonb then perform 1 from pro_appointment_requests where id=(old_input->'client'->>'requestId')::uuid and owner_id=p_actor and work_id=wid for share;end if;
 if jsonb_typeof(old_input->'team') is distinct from 'array' then raise exception 'Invalid team audience' using errcode='22023';end if;
 for gref in select value from jsonb_array_elements(old_input->'team') order by value->>'grantId' loop perform 1 from pro_team_grants where id=(gref->>'grantId')::uuid and owner_id=p_actor and work_id=wid for share;end loop;
 select * into l from pro_daily_logs where owner_id=p_actor and work_id=wid and id=lid for update;if not found then raise exception 'Log unavailable' using errcode='42501';end if;
 if p_input?'files' then
  if jsonb_typeof(p_input->'files') is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(p_input->'files')key) is distinct from array['client','revision','team'] or jsonb_typeof(p_input->'files'->'revision') is distinct from 'number' or not coalesce((p_input->'files'->>'revision')~'^[0-9]{1,10}$',false) or(p_input->'files'->>'revision')::numeric not between 0 and 2147483647 then raise exception 'Invalid file selection' using errcode='22023';end if;
  select revision into head from pro_daily_log_file_heads where owner_id=p_actor and work_id=wid and log_id=lid;head:=coalesce(head,0);if head<>(p_input->'files'->>'revision')::integer then raise exception 'Private files changed' using errcode='40001';end if;
  foreach channel_name in array array['client','team'] loop
   if jsonb_typeof(p_input->'files'->channel_name) is distinct from 'array' or jsonb_array_length(p_input->'files'->channel_name)>20 or(channel_name='client' and old_input->'client'='null'::jsonb or channel_name='team' and jsonb_array_length(old_input->'team')=0) and jsonb_array_length(p_input->'files'->channel_name)>0 then raise exception 'Files require their publication audience' using errcode='22023';end if;
   selected:='{}';for ref in select value from jsonb_array_elements(p_input->'files'->channel_name) loop
    if jsonb_typeof(ref) is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(ref)key) is distinct from array['id','sha256'] or jsonb_typeof(ref->'id') is distinct from 'string' or not coalesce((ref->>'sha256')~'^[a-f0-9]{64}$',false) then raise exception 'Invalid selected file' using errcode='22023';end if;
    if(ref->>'id')::uuid=any(selected) then raise exception 'Duplicate selected file' using errcode='22023';end if;selected:=array_append(selected,(ref->>'id')::uuid);
    select * into f from pro_daily_log_files where id=(ref->>'id')::uuid and owner_id=p_actor and work_id=wid and log_id=lid and ready for share;if not found or f.sha256<>ref->>'sha256' then raise exception 'Selected file changed or unavailable' using errcode='40001';end if;
    snap:=pro_daily_log_file_snapshot(f);if channel_name='client' then client_files:=client_files||jsonb_build_array(snap);else team_files:=team_files||jsonb_build_array(snap);end if;
   end loop;
  end loop;
 end if;
 publication:=pro_daily_logs_mutate(p_actor,old_input);ver:=(publication->'version'->>'version')::integer;
 foreach channel_name in array array['client','team'] loop pos:=0;for snap in select value from jsonb_array_elements(case when channel_name='client' then client_files else team_files end) loop insert into pro_daily_log_published_files values(p_actor,wid,lid,ver,channel_name,(snap->>'id')::uuid,pos,snap);pos:=pos+1;end loop;end loop;
 answer:=jsonb_build_object('action','publish','publication',publication,'files',jsonb_build_object('client',client_files,'team',team_files));perform pro_work_schedule_owner(p_actor,wid);
 insert into pro_daily_log_file_actions(actor_id,action_id,owner_id,work_id,log_id,input,input_hash,result,before_state,after_state) values(p_actor,aid,p_actor,wid,lid,p_input,p_input_hash,answer,pro_daily_log_json(l),answer);return answer;
end $$;
create or replace function public.pro_daily_log_file_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_daily_log_file_actions;ctx jsonb;begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from pro_daily_log_file_actions where actor_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;
 if r.input->>'action'='publish' then perform pro_work_schedule_owner(p_actor,r.work_id);else ctx:=pro_daily_log_file_context(p_actor,r.work_id,r.log_id,r.grant_id,true);if(ctx->>'generation')::uuid is distinct from r.generation then raise exception 'Receipt generation changed' using errcode='42501';end if;end if;
 if r.result is null then return jsonb_build_object('receipt',null);end if;return jsonb_build_object('receipt',jsonb_build_object('inputHash',r.input_hash,'result',r.result));end $$;
create or replace function public.pro_daily_log_file_legacy_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_daily_log_file_actions;begin
 select * into r from pro_daily_log_file_actions where actor_id=p_actor and action_id=p_action;if found then perform pro_work_schedule_owner(p_actor,r.work_id);if r.input->>'action'<>'publish' or r.input?'files' then raise exception 'Action belongs to the attachment flow' using errcode='22023';end if;end if;return pro_daily_log_action_read(p_actor,p_action);end $$;
create or replace function public.pro_daily_log_file_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin if old.ready or not new.ready or new.ready_revision is null or(to_jsonb(new)-array['ready','ready_revision']) is distinct from(to_jsonb(old)-array['ready','ready_revision']) then raise exception 'Daily log file is immutable' using errcode='23514';end if;return new;end $$;
create or replace function public.pro_daily_log_file_action_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin if old.result is not null or new.result is null or(to_jsonb(new)-array['result','after_state']) is distinct from(to_jsonb(old)-array['result','after_state']) then raise exception 'Daily log file receipt is immutable' using errcode='23514';end if;return new;end $$;
drop trigger if exists pro_daily_log_file_immutable on pro_daily_log_files;create trigger pro_daily_log_file_immutable before update on pro_daily_log_files for each row execute function pro_daily_log_file_immutable();
drop trigger if exists pro_daily_log_file_action_immutable on pro_daily_log_file_actions;create trigger pro_daily_log_file_action_immutable before update on pro_daily_log_file_actions for each row execute function pro_daily_log_file_action_immutable();
drop trigger if exists pro_daily_log_published_file_immutable on pro_daily_log_published_files;create trigger pro_daily_log_published_file_immutable before update on pro_daily_log_published_files for each row execute function pro_team_append_only();
do $$declare tab text;f record;begin foreach tab in array array['pro_daily_log_file_heads','pro_daily_log_files','pro_daily_log_file_actions','pro_daily_log_published_files'] loop execute format('alter table public.%I enable row level security',tab);execute format('revoke all on public.%I from public,anon,authenticated',tab);execute format('grant all on public.%I to service_role',tab);end loop;
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_daily_log_file_json','pro_daily_log_file_snapshot','pro_daily_log_file_context','pro_daily_log_file_head_advance','pro_daily_log_files_read','pro_daily_log_published_files_read','pro_daily_log_file_download','pro_daily_log_file_pending','pro_daily_log_file_reserve','pro_daily_log_file_ready','pro_daily_log_publish_files','pro_daily_log_file_action_read','pro_daily_log_file_legacy_action_read','pro_daily_log_file_immutable','pro_daily_log_file_action_immutable') loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
do $$begin if to_regclass('storage.buckets') is not null then insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('pro-daily-log-files','pro-daily-log-files',false,20971520,array['image/jpeg','application/pdf']) on conflict(id) do update set file_size_limit=excluded.file_size_limit;if not exists(select 1 from storage.buckets where id='pro-daily-log-files' and not public and file_size_limit=20971520 and cardinality(allowed_mime_types)=2 and allowed_mime_types @> array['image/jpeg','application/pdf']) then raise exception 'Private daily log bucket contract mismatch';end if;end if;
 if to_regclass('storage.objects') is not null then execute 'drop policy if exists pro_daily_log_files_no_direct on storage.objects';execute 'create policy pro_daily_log_files_no_direct on storage.objects as restrictive for all to anon,authenticated using(bucket_id <> ''pro-daily-log-files'') with check(bucket_id <> ''pro-daily-log-files'')';end if;end $$;
commit;
